{
  "title": "The Glass Diver's Bridge",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver surfaces in a ruined plaza.",
      "visual_description": "A cracked marble plaza overgrown with thorny vines, broken royal banners flapping in the twilight, and a single oil lamp flickering atop a tilted fountain.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "Mara spreads her map on a fallen pillar.",
      "visual_description": "Mara unrolls a stained parchment across a chipped stone pillar, her brass compass glowing faintly as she traces the route through the city's skeletal remains.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of cursed towers.",
      "visual_description": "The oracle lamp's single eye blazes orange as its flame flickers toward a distant twisted spire where strange lights pulse behind barred windows.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts the castle gates.",
      "visual_description": "The small metal fox crouches behind a toppled statue, its blue glass eyes scanning the iron portcullis that groans in the wind, rusted chains hanging loose.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping tax collector blocks the gatehouse.",
      "visual_description": "Inside the gatehouse a figure slumps over a ledger book, stamped papers fluttering from his sleeves, snoring softly amid piles of dust and cobwebs.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara negotiates with the dozing official.",
      "visual_description": "Mara leans over the sleeping tax collector, tapping his shoulder while holding up a compass; his half-lidded eyes barely register her presence as he mumbles about tariffs.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver swims through a mirror to bypass the gates.",
      "visual_description": "The glass diver presses his helmet against a tall standing mirror that reflects the ruined courtyard; his form shimmers and passes through the glass into a silvery passage.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Inside the mirror world, the glass diver sees a hidden path.",
      "visual_description": "A reversed version of the city stretches under a violet sky, with luminous footprints leading toward a magic door that glows from within the reflection.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The tin fox discovers an armored patrol near the barracks.",
      "visual_description": "The tin fox peeks around a corner of a collapsed barracks, watching a line of hollow armor suits clank past on an empty street, their visors dark.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Mara and the oracle lamp find a hidden map room.",
      "visual_description": "Mara lights a brazier in a circular room where a stone table holds a mosaic map of the city; the oracle lamp floats above, its flame casting moving shadows.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector wakes briefly to stamp a permission slip.",
      "visual_description": "Yawning, the tax collector stamps a random paper with a seal and shoves it into Mara's hands, then immediately falls back asleep on his ledger pillow.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver exits the mirror onto a haunted rampart.",
      "visual_description": "The glass diver steps out of a shattered window onto a stone rampart lined with old royal standards that whisper in the wind, shadows writhing at the edges.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The tin fox triggers a trap near the magic door.",
      "visual_description": "A wire snaps as the tin fox scurries over a loose stone; a net of chains drops from above, but the fox darts aside, its tail-wind key spinning.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Mara reads the map and finds the route to the bridge.",
      "visual_description": "By the oracle lamp's glow, Mara traces a winding path through the city ruins that ends at a narrow bridge spanning a dark chasm.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver opens the magic door with a mirrored key.",
      "visual_description": "The glass diver pulls a shard of mirror from his coat and turns it in the lock of a black stone door; the door swings open to reveal a stairway upward.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The group reunites at the base of the bridge.",
      "visual_description": "Mara, the glass diver, the tin fox, and the oracle lamp gather at the foot of a crumbling stone bridge that arches over a mist-filled gorge, broken banners draped on its rails.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The sleeping tax collector appears with a final debt demand.",
      "visual_description": "The tax collector stumbles onto the bridge, blinking sleepily and waving a paper, demanding an exit toll as the bridge trembles beneath everyone's feet.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The glass diver shatters a mirror to escape across the bridge.",
      "visual_description": "The glass diver throws a hand mirror onto the bridge, which splinters into a shower of reflective shards that momentarily blind the patrol suits and the tax collector; the group dashes across as the bridge collapses behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

